// Pessoas que podem registrar no Assessor (número com DDI 55 → nome).
const PESSOAS = { '5511930851325': 'Daniel', '5511930859309': 'Quézia', '5511920853779': 'Eliezer' };
// IDs @lid do WhatsApp → número (o WhatsApp às vezes manda só o LID no grupo).
const LIDS = { '144770513031177': '5511930851325', '255258647359543': '5511930859309', '137357852426442': '5511920853779' };
// Grupos onde o Assessor atende. Em conversa privada, só a conversa "consigo mesmo" do Daniel é atendida.
const GRUPOS = ['120363412854461070@g.us']; // DM Assessor Pessoal
const ZW = String.fromCharCode(8203); // marcador invisível colocado nas mensagens enviadas pelo bot (evita loop)
const digitos = s => String(s || '').split('@')[0].split(':')[0].replace(/\D/g, '');
const saida = [];
// Identidade de clientes do piloto vem do Supabase (nó anterior).
let idn = {};
try { idn = $input.first().json || {}; } catch (e) { idn = {}; }
for (const item of $('Recebe WhatsApp (Evolution)').all()) {
  const raw = item.json.body ?? item.json;
  const evento = String(raw.event || '').toLowerCase().replace('_', '.');
  if (evento && evento !== 'messages.upsert') continue;
  const instancia = String(raw.instance || '').toLowerCase() === 'dyno' ? 'dyno' : 'pesquisa-aereo';
  const d = Array.isArray(raw.data) ? (raw.data[0] || {}) : (raw.data || {});
  const key = d.key || {};
  const jid = String(key.remoteJid || '');
  if (!jid || jid.includes('broadcast') || jid.includes('newsletter')) continue;
  const fromMe = key.fromMe === true;
  const dono = digitos(raw.sender);
  const ehGrupo = jid.endsWith('@g.us');
  let destino, remetente, conversaComigoMesmo = false;
  if (ehGrupo) {
    if (instancia !== 'dyno') continue; // grupos são atendidos pelo número do Dyno
    if (!GRUPOS.includes(jid)) continue;
    if (fromMe) continue;
    destino = jid;
    const part = String(key.participantAlt || key.participantPn || d.participantPn || key.participant || '');
    remetente = fromMe ? dono : (part.endsWith('@lid') ? (LIDS[digitos(part)] || digitos(part)) : digitos(part));
  } else {
    const alt = key.remoteJidAlt || key.senderPn || d.senderPn || '';
    destino = jid.endsWith('@lid') ? digitos(alt) : digitos(jid);
    if (instancia === 'dyno') {
      // Número do Dyno: atende conversas privadas de quem está na lista (PESSOAS); ignora o que o próprio número envia.
      if (fromMe || !destino) continue;
      remetente = destino;
    } else {
      conversaComigoMesmo = fromMe && !!destino && destino === dono;
      if (!conversaComigoMesmo) continue; // o WhatsApp conectado é o do Daniel: não responder conversas com outras pessoas
      remetente = conversaComigoMesmo ? dono : destino;
    }
  }
  const m = d.message || {};
  const docMsg = m.documentMessage || (m.documentWithCaptionMessage && m.documentWithCaptionMessage.message && m.documentWithCaptionMessage.message.documentMessage) || null;
  let texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || (m.imageMessage && m.imageMessage.caption) || (m.videoMessage && m.videoMessage.caption) || (docMsg && docMsg.caption) || '';
  if (m.buttonsResponseMessage) texto = m.buttonsResponseMessage.selectedDisplayText || texto;
  if (m.listResponseMessage) texto = m.listResponseMessage.title || texto;
  // Contato compartilhado (cartão de contato): vira texto para o assistente entender (ex.: pedido de convite).
  const cards = [];
  if (m.contactMessage) cards.push(m.contactMessage);
  if (m.contactsArrayMessage && Array.isArray(m.contactsArrayMessage.contacts)) cards.push(...m.contactsArrayMessage.contacts);
  if (cards.length && !texto) {
    texto = cards.slice(0, 5).map(c => {
      const v = String(c.vcard || '');
      const waid = (v.match(/waid=(\d+)/) || [])[1];
      const tel = (v.match(/TEL[^:\n]*:([+\d\s().-]+)/) || [])[1];
      const num = waid ? '+' + waid : (tel ? tel.trim() : 'sem número');
      return '[contato compartilhado: ' + String(c.displayName || 'sem nome') + ' — ' + num + ']';
    }).join(' ');
  }
  const audio = !!m.audioMessage || d.messageType === 'audioMessage';
  const imagem = !!m.imageMessage || d.messageType === 'imageMessage';
  const pdf = !!docMsg && /pdf/i.test(String(docMsg.mimetype || docMsg.fileName || ''));
  const arquivo_nome = docMsg ? String(docMsg.fileName || docMsg.title || 'documento.pdf') : '';
  const docNome = docMsg ? String(docMsg.fileName || docMsg.title || '') : '';
  const arquivo_mime = docMsg ? String(docMsg.mimetype || '') : '';
  const planilha = !!docMsg && !pdf && (/csv|ofx|sheet|excel|text\/plain/i.test(arquivo_mime) || /\.(csv|ofx|qfx|xlsx?|txt)$/i.test(docNome));
  const dicaExtrato = /\b(extrato|fatura|statement)\b/i.test(String(texto) + ' ' + docNome) || /\.(ofx|qfx)$/i.test(docNome);
  const tnorm = String(texto || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const importar = instancia === 'dyno' && ((pdf && dicaExtrato) || planilha || /^(sim,?\s*)?importar[.!]*$/.test(tnorm) || /^nao importar[.!]*$/.test(tnorm));
  const locMsg = m.locationMessage || m.liveLocationMessage || null;
  const localizacao = locMsg && locMsg.degreesLatitude != null ? { lat: Number(locMsg.degreesLatitude), lng: Number(locMsg.degreesLongitude), nome: String(locMsg.name || ''), endereco: String(locMsg.address || '') } : null;
  if (locMsg && !texto) texto = String(locMsg.comment || locMsg.caption || '');
  if (String(texto).startsWith(ZW)) continue;
  if (!texto && !audio && !imagem && !pdf && !planilha && !localizacao) continue;
  let autor = PESSOAS[remetente];
  let cliente = false;
  if (!autor && instancia === 'dyno' && !ehGrupo && idn.atender === true && idn.autor && !Object.values(PESSOAS).includes(idn.autor)) { autor = String(idn.autor); cliente = true; }
  if (!autor) continue;
  saida.push({ json: { numero: destino, remetente, autor, jid, grupo: ehGrupo, nome: d.pushName || '', texto: String(texto).trim(), audio, imagem, pdf, arquivo_nome, localizacao, messageId: key.id || '', importar, planilha, arquivo_mime, conversaComigoMesmo, instancia, cliente, familia: !cliente, nome_exibicao: cliente ? (idn.nome || autor) : autor } });
}
return saida.slice(0, 1);

const base = $('Normalizar mensagem').first().json;
let texto = base.texto || '';
let drive_link = '';
if (base.audio) {
  let t = '';
  try { t = $('Transcrever áudio').first().json.text || ''; } catch (e) { t = ''; }
  texto = t ? ('[áudio transcrito] ' + t) : (texto || ('[' + (base.autor || 'o usuário') + ' enviou um áudio que não pôde ser transcrito; peça para escrever]'));
}
if (base.imagem || base.pdf) {
  try { drive_link = $('Salvar foto no Drive').first().json.webViewLink || ''; } catch (e) { drive_link = ''; }
  if (!texto) texto = base.pdf ? '(PDF enviado sem legenda: ' + base.arquivo_nome + ')' : '(foto enviada sem legenda)';
}
if (base.localizacao) {
  const l = base.localizacao;
  const desc = [l.nome, l.endereco].filter(Boolean).join(' - ');
  texto = (texto ? texto + ' ' : '') + '[📍 localização enviada: lat ' + l.lat + ', lng ' + l.lng + (desc ? ' (' + desc + ')' : '') + ']';
}
return [{ json: { ...base, texto, drive_link } }];

const TZ = 'America/Sao_Paulo';
const MODELO = 'gpt-5.6-luna';
const entrada = $('Preparar entrada').first().json;
const linhas = n => $(n).all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null);
const fmt = v => v ? DateTime.fromISO(String(v)).setZone(TZ).setLocale('pt-BR').toFormat('dd/LL/yyyy HH:mm (ccc)') : null;
const agora = DateTime.now().setZone(TZ).setLocale('pt-BR');
const r2 = x => Math.round(x * 100) / 100;

const EU = entrada.autor || 'Daniel';
const de = r => r.autor || 'Daniel';
const FAM = ['Daniel', 'Quézia', 'Eliezer'].includes(EU);
const fotoBaixada = () => { for (const n of ['Baixar foto (Evolution) (Dyno)', 'Baixar foto (Evolution)']) { try { const j = $(n).first().json; if (j && j.base64) return j; } catch (e) { } } return null; };
// Centro de contas individual: o contexto só contém dados de quem enviou a mensagem.
const memorias = linhas('Buscar memórias').filter(r => { const s = r.pessoa || 'Daniel'; return s === EU || (FAM && (s === 'todos' || (s === 'ambos' && (EU === 'Daniel' || EU === 'Quézia')))); }).map(r => ({ id: r.id, sobre: r.pessoa || 'Daniel', categoria: r.categoria, conteudo: r.conteudo }));
const tarefas = linhas('Buscar tarefas abertas').filter(r => de(r) === EU).map(r => ({ id: r.id, titulo: r.titulo, prioridade: r.prioridade, prazo: fmt(r.prazo), notas: r.notas || undefined }));
const lembretes = linhas('Buscar lembretes pendentes').filter(r => de(r) === EU).map(r => r.status === 'aguardando' ? ({ id: r.id, texto: r.texto, status: 'aguardando_confirmacao', ja_avisado_vezes: r.insistencias || 1, recorrencia: r.recorrencia, conta_id: r.conta_id || undefined }) : ({ id: r.id, texto: r.texto, quando: fmt(r.quando), recorrencia: r.recorrencia }));
const trans = linhas('Buscar transações').filter(r => de(r) === EU).map(r => ({ ...r, dt: DateTime.fromISO(String(r.data || r.createdAt)).setZone(TZ) }));

function resumo(lista) {
  const o = { receitas: 0, despesas: 0, por_categoria: {} };
  for (const t of lista) {
    const v = Number(t.valor) || 0;
    if (t.tipo === 'receita') o.receitas += v;
    else { o.despesas += v; const c = t.categoria || 'outros'; o.por_categoria[c] = (o.por_categoria[c] || 0) + v; }
  }
  o.saldo = r2(o.receitas - o.despesas); o.receitas = r2(o.receitas); o.despesas = r2(o.despesas);
  o.por_categoria = Object.fromEntries(Object.entries(o.por_categoria).sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, r2(v)]));
  o.qtd_lancamentos = lista.length;
  return o;
}
const iniMes = agora.startOf('month');
const iniMesAnt = iniMes.minus({ months: 1 });
const doMes = trans.filter(t => t.dt >= iniMes);
const financas = {
  titular: EU,
  hoje: resumo(trans.filter(t => t.dt >= agora.startOf('day'))),
  ultimos_7_dias: resumo(trans.filter(t => t.dt >= agora.minus({ days: 7 }).startOf('day'))),
  mes_atual: resumo(doMes),
  maiores_despesas_mes_atual: doMes.filter(t => t.tipo !== 'receita').sort((a, b) => (Number(b.valor) || 0) - (Number(a.valor) || 0)).slice(0, 10).map(t => ({ data: t.dt.toFormat('dd/LL'), valor: t.valor, categoria: t.categoria, descricao: t.descricao })),
  mes_anterior: resumo(trans.filter(t => t.dt >= iniMesAnt && t.dt < iniMes)),
  ultimas_transacoes: trans.sort((a, b) => b.dt - a.dt).slice(0, 40).map(t => ({ id: t.id, data: t.dt.toFormat('dd/LL/yyyy'), tipo: t.tipo, valor: t.valor, categoria: t.categoria, descricao: t.descricao, comprovante: t.comprovante_url || undefined, forma_pagamento: t.forma_pagamento || undefined }))
};
const gastoMesCat = financas.mes_atual.por_categoria;
const orcamentos = linhas('Buscar orçamentos').filter(r => r.ativo !== false && (r.pessoa || 'Daniel') === EU).map(r => { const g = gastoMesCat[r.categoria] || 0; const lim = Number(r.limite) || 0; return { categoria: r.categoria, limite_mensal: lim, gasto_mes: g, usado_pct: lim ? Math.round(g / lim * 100) : null, restante: r2(lim - g) }; });
const diaF = v => v ? DateTime.fromISO(String(v)).setZone(TZ).setLocale('pt-BR').toFormat('dd/LL/yyyy (ccc)') : null;
const contas = linhas('Buscar contas abertas').filter(r => de(r) === EU).sort((a, b) => String(a.vencimento).localeCompare(String(b.vencimento))).map(r => ({ id: r.id, descricao: r.descricao, valor: r.valor, vencimento: diaF(r.vencimento), dias_para_vencer: r.vencimento ? Math.round(DateTime.fromISO(String(r.vencimento)).setZone(TZ).startOf('day').diff(agora.startOf('day'), 'days').days) : null, beneficiario: r.beneficiario || undefined, recorrencia: r.recorrencia, tem_linha_digitavel: !!r.linha_digitavel }));
const assinaturasL = linhas('Buscar assinaturas').filter(r => de(r) === EU && r.ativo !== false);
const assinaturas = { itens: assinaturasL.map(r => ({ id: r.id, nome: r.nome, valor: r.valor, ciclo: r.ciclo, proxima_cobranca: diaF(r.proxima_cobranca) })), total_mensal_equivalente: r2(assinaturasL.reduce((t, r) => t + (Number(r.valor) || 0) / (r.ciclo === 'anual' ? 12 : 1), 0)), total_anual: r2(assinaturasL.reduce((t, r) => t + (Number(r.valor) || 0) * (r.ciclo === 'anual' ? 1 : 12), 0)) };
const veiculos = linhas('Buscar veículos').filter(r => de(r) === EU && r.ativo !== false).map(r => { const dias = r.km_data ? agora.diff(DateTime.fromISO(String(r.km_data)), 'days').days : 0; return { apelido: r.apelido, km_informado: r.km_atual, informado_em: diaF(r.km_data), km_estimado_hoje: r.km_atual != null ? Math.round(r.km_atual + (Number(r.km_por_dia) || 0) * dias) : null }; });
const manutencoes = linhas('Buscar manutenções').filter(r => de(r) === EU && r.ativo !== false).map(r => ({ id: r.id, item: r.item, bem: r.bem, a_cada_dias: r.intervalo_dias || undefined, a_cada_km: r.intervalo_km || undefined, ultima: diaF(r.ultima_data), ultima_km: r.ultima_km ?? undefined, proxima_data: diaF(r.proxima_data), proxima_km: r.proxima_km ?? undefined }));
const ehMeuHistorico = r => r.papel === 'assistente'
  ? (r.autor === 'Assessor:' + EU || ((!r.autor || r.autor === 'Assessor') && EU === 'Daniel'))
  : de(r) === EU;
const historico = linhas('Buscar histórico').filter(ehMeuHistorico).slice(0, 14).reverse().map(r => ({ role: r.papel === 'assistente' ? 'assistant' : 'user', content: (r.papel === 'assistente' ? '' : '[' + de(r) + '] ') + String(r.texto || '').slice(0, 1500) }));

const sistema = [
  'Seu nome é *Dyno*. Você é o Dyno, assessor pessoal no WhatsApp ' + (FAM ? '(grupo "DM Assessor Pessoal") de Daniel, Quézia e Eliezer.' : 'de ' + EU + ' (conversa privada).') + ' CADA PESSOA TEM SEU PRÓPRIO CENTRO DE CONTAS: finanças, tarefas, lembretes e memórias são individuais. O CONTEXTO abaixo contém SOMENTE os dados de quem está falando agora. Nunca revele, estime ou comente gastos, tarefas ou lembretes de outra pessoa; se pedirem, explique gentilmente que cada um só vê o próprio. ESTILO: fale em português do Brasil como um amigo próximo' + (FAM ? ' da família' : '') + ' — informal, leve, bem-humorado e curto (mensagem de WhatsApp: no máximo ~8 linhas; *negrito* com moderação; nada de títulos markdown; emoji só de vez em quando). Chame a pessoa pelo nome. Evite respostas robóticas como "Anotado:" ou "Registrado:".',
  'APRESENTAÇÃO: sempre que for se apresentar — em cumprimentos (oi, olá, bom dia...), quando perguntarem quem você é ou o que faz, ou na primeira conversa com alguém — comece exatamente com: "Olá, sou o Dyno, seu assessor pessoal." Se perguntarem seu nome, você é o Dyno. Nas demais respostas (registros, consultas), vá direto ao ponto sem se reapresentar.',
  FAM ? '' : 'CLIENTE DO PILOTO: esta conta é só de ' + EU + ' (chame de ' + (entrada.nome_exibicao || EU) + '). Não existe grupo nem outras pessoas nesta conta. Nunca mencione Daniel, Quézia, Eliezer, família Marim ou dados de outros usuários; nos exemplos de resposta, troque os nomes pelo nome de quem está falando.',
  'Agora: ' + agora.toFormat('cccc, dd/LL/yyyy HH:mm') + ' (fuso America/Sao_Paulo, UTC-03:00).',
  'A mensagem atual é de: ' + EU + '. Trate "meu/minha/eu" como sendo ' + EU + '. Chame a pessoa pelo nome quando fizer sentido.',
  '',
  'Você cuida de: finanças pessoais (gastos e receitas), tarefas, lembretes, memória de longo prazo, contas a pagar, assinaturas, manutenções da casa e do carro e busca de lugares perto.',
  'Responda SEMPRE com um único objeto JSON válido no formato {"resposta": string, "acoes": array}.',
  'Ações possíveis (só gere quando pedirem ou informar algo que deva ser registrado):',
  '- {"tipo":"registrar_transacao","movimento":"despesa"|"receita","valor":number,"categoria":string,"descricao":string,"data":"YYYY-MM-DDTHH:mm:ss-03:00","forma_pagamento":string|null}',
  '- {"tipo":"apagar_transacao","id":number}',
  '- {"tipo":"criar_tarefa","titulo":string,"prioridade":"alta"|"media"|"baixa","prazo":"YYYY-MM-DDTHH:mm:ss-03:00"|null,"notas":string|null}',
  '- {"tipo":"atualizar_tarefa","id":number,"status":"concluida"|"cancelada"|"aberta"}',
  '- {"tipo":"criar_lembrete","texto":string,"quando":"YYYY-MM-DDTHH:mm:ss-03:00","recorrencia":"nenhuma"|"diaria"|"semanal"|"mensal"}',
  '- {"tipo":"cancelar_lembrete","id":number}  (cancela de vez, inclusive as próximas repetições)',
  '- {"tipo":"confirmar_lembrete","id":number}  (pessoa confirmou que viu/fez um lembrete aguardando_confirmacao)',
  '- {"tipo":"adiar_lembrete","id":number,"minutos":number}  (lembrar de novo daqui a X minutos)',
  '- {"tipo":"salvar_memoria","conteudo":string,"categoria":"pessoal"|"preferencia"|"trabalho"|"saude"|"financas"|"familia"|"endereco"|"outro","sobre":' + (FAM ? '"Daniel"|"Quézia"|"Eliezer"|"todos"' : JSON.stringify(EU)) + '}',
  '- {"tipo":"esquecer_memoria","id":number}',
  '- {"tipo":"definir_orcamento","categoria":string,"limite":number}  (orçamento MENSAL da categoria; usa as mesmas categorias de despesa da regra 1; redefinir substitui o valor)',
  '- {"tipo":"remover_orcamento","categoria":string}',
  '- {"tipo":"criar_conta","descricao":string,"valor":number|null,"vencimento":"YYYY-MM-DD","beneficiario":string|null,"linha_digitavel":string|null,"categoria":string,"recorrencia":"nenhuma"|"mensal"}  (conta a pagar; o sistema cria sozinho os avisos de 3 dias antes e do dia)',
