  '- {"tipo":"editar_assinatura","id":number,"nome":string|null,"valor":number|null,"ciclo":"mensal"|"anual"|null,"proxima_cobranca":"YYYY-MM-DD"|null}',
  '- {"tipo":"cancelar_assinatura","id":number}  (para de acompanhar; lembre a pessoa de cancelar também no serviço)',
